import{sceneProgress,motionProgress}from'../../../assets/voice-timing.mjs';
import{COLORS}from'../../../assets/core.mjs';import{board}from'../../02/teaching/visuals.mjs';import{BASE03,BEST03,metricsReport,TRADEOFF03,CANDIDATES03,THREE03}from'../../../assets/metrics03.mjs';import{describeError02}from'../../../assets/legality02.mjs';
const E=s=>String(s).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;');
const T=(x,y,s,size=24,color='#244d40',anchor='middle')=>`<text x="${x}" y="${y}" font-size="${size}" fill="${color}" text-anchor="${anchor}">${E(s)}</text>`;
const R=(x,y,w,h,fill='#eef4e8',stroke='#b7c9b5',extra='')=>`<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="3" fill="${fill}" stroke="${stroke}" ${extra}/>`;
const f=n=>Number.isInteger(n)?String(n):n.toFixed(2),pct=n=>n==null?'—':f(100*n)+'%';
function mini(rows,x,y,w,h,label){const minx=Math.min(...rows.map(r=>r[1])),miny=Math.min(...rows.map(r=>r[2])),maxx=Math.max(...rows.map(r=>r[1]+r[3])),maxy=Math.max(...rows.map(r=>r[2]+r[4])),W=maxx-minx,H=maxy-miny,u=Math.min(w/W,h/H),ox=x+(w-W*u)/2,oy=y+(h-H*u)/2;let s=R(ox,oy,W*u,H*u,'#f6faf0','#658b70');rows.forEach((r,i)=>{const c=COLORS[r[0]]||['#437ba5','#c08a42','#8f76b5'][i%3];s+=R(ox+(r[1]-minx)*u,oy+(maxy-r[2]-r[4])*u,r[3]*u,r[4]*u,c,'#fff')+T(ox+(r[1]-minx+r[3]/2)*u,oy+(maxy-r[2]-r[4]/2)*u+5,r[0],Math.min(25,u*.7),'#fff');});return s+T(x+w/2,y+h+30,label,21);}
function boxed(rows,outline,opts={}){const{x=55,y=100,w=550,h=335,catalog=undefined,interactive=true}=opts,r=metricsReport(rows,outline,catalog);let s=board(rows,outline,{x,y,w,h,interactive});if(r.bbox){const u=Math.min(w/outline[0],h/outline[1]),ox=x+(w-outline[0]*u)/2,oy=y+(h-outline[1]*u)/2,b=r.bbox;s+=R(ox+b.xmin*u,oy+(outline[1]-b.ymax)*u,b.width*u,b.height*u,'none',r.legal?'#2a6a4a':'#a7563f','stroke-width="2" stroke-dasharray="5 3" pointer-events="none"');}return s;}
export function renderScene(scene,time,trial,reduced){const p=sceneProgress(scene,time),o=scene.outline||[10,8];let rows=trial||scene.rows,body='',moving=false;
 if(!trial&&scene.from){const q=reduced?1:Math.max(0,Math.min(1,(time-scene.start-1)/3)),v=q*q*(3-2*q);moving=q<1;rows=scene.rows.map((r,i)=>r.map((n,j)=>j===1||j===2?scene.from[i][j]+(n-scene.from[i][j])*v:n));}
 const report=metricsReport(rows,o,scene.catalog);
 if(trial){body=boxed(rows,o,{x:40,y:105,w:570,h:315,catalog:scene.catalog});body+=T(755,160,report.legal?'当前布局合法':'先处理布局错误',27,report.legal?'#326d4d':'#a44f35');body+=T(755,230,'盒面积 '+(report.bbox?f(report.bbox.area):'—'),25)+T(755,300,'外框密度 '+pct(report.outline_density),22)+T(755,370,'盒密度 '+pct(report.packing_density),22);}
 else if(scene.view==='intro-select'){body=mini(BASE03,60,150,390,215,'摆法一')+mini(BEST03,510,150,390,215,'摆法二')+T(255,110,'同样合法',25)+T(705,110,'同样合法',25)+T(480,440,'按什么挑？先说清目标，再说清分母',27,'#9a5833');}
 else if(scene.view==='intro-goal'){const lines=[['先接Lab2检查','非法布局不参加排名'],['再算真实包围盒','宽=右−左，高=上−下'],['两个密度分开写','外框分母80；包围盒分母是盒子'],['输出带依据的报告','后面的解码与搜索都靠它']];lines.forEach((a,i)=>{const y=120+i*82;body+=R(90,y,780,66,p*4>=i?'#e3efdd':'#f2f6ee')+T(120,y+26,a[0],24,'#355b46','start')+T(120,y+52,a[1],19,'#5e7565','start');});}
 else if(scene.view==='area'){BASE03.forEach((r,i)=>{const x=45+i*178,th=.05+i*.12,show=Math.max(0,Math.min(1,(p-th)/.1));if(show<=0)return;body+=`<g opacity="${show.toFixed(2)}" transform="translate(0 ${((1-show)*18).toFixed(1)})">`+R(x,135,158,185,COLORS[r[0]],'#fff')+T(x+79,190,r[0],37,'#fff')+T(x+79,250,r[3]+'×'+r[4]+'='+r[3]*r[4],23,'#fff')+'</g>';});if(p>.72)body+=T(480,410,'模块面积和 = 6+6+4+3+4 = 23',30,'#8a5a26');if(p>.8)body+=T(480,455,'外框没变，这个和也不会变',22,'#5e7565');}
 else if(['outline','bbox','baseline-score','compact'].includes(scene.view)){body=boxed(rows,o,{x:45,y:110,w:550,h:320});if(!moving){body+=T(745,155,'模块面积 23',27)+T(745,220,scene.view==='outline'?'固定外框面积80':`包围盒 ${report.bbox.width}×${report.bbox.height}=${report.bbox.area}`,26);if(p>.25)body+=T(745,305,scene.view==='outline'?'23 / 80 = 28.75%':`盒内空余 ${report.bbox.area}−23=${report.bbox_dead}`,23);}else body+=T(740,250,'先看重新摆放',24);}
 else if(scene.view==='same-outline'){body=boxed(BASE03,[10,8],{x:35,y:145,w:410,h:265,interactive:false})+boxed(BEST03,[10,8],{x:515,y:145,w:410,h:265,interactive:false})+T(240,110,'原摆法',25)+T(720,110,'压紧后',25)+T(240,450,'23 / 80 = 28.75%',23)+T(720,450,'23 / 80 = 28.75%',23);}
 else if(scene.view==='extents'||scene.view==='translation-bug'){body=boxed(rows,o,{x:35,y:120,w:530,h:305});if(!moving){body+=T(755,150,'xmin=1，xmax=10',24)+T(755,215,'ymin=2，ymax=5',24);if(scene.view==='extents')body+=T(755,310,'宽10−1=9',28)+T(755,385,'高5−2=3',28);else body+=T(755,310,'错误：10×5=50',26,'#ad5639')+T(755,385,'正确：9×3=27',26,'#356f4b');}}
 else if(scene.view==='density-compare'){body=mini(BASE03,45,155,390,210,'9×3=27')+mini(BEST03,525,155,390,210,'6×4=24')+T(240,105,'原合法布局',24)+T(720,105,'新合法布局',24);body+=T(240,455,'23/27 ≈ 85.19%',27)+T(720,455,'23/24 ≈ 95.83%',27);}
 else if(scene.view==='accounting'){const lines=[['模块面积','23','23'],['固定外框面积','80','80'],['外框空余','57','57'],['包围盒面积','27','24'],['盒内空余','4','1']];body=T(480,110,'先分清固定外框，再看跟着摆法变的盒子',26);lines.forEach((a,i)=>{const th=.05+i*.13,show=Math.max(0,Math.min(1,(p-th)/.1));if(show<=0)return;body+=R(90,145+i*58,780,50,i>=3?'#e3efdd':'#f2f6ee',i===4?'#c9a06d':'#b7c9b5')+T(120,179+i*58,a[0],22,'#355b46','start')+T(560,179+i*58,a[1],24)+T(760,179+i*58,a[2],24);});}
 else if(scene.view==='invalid'||scene.view==='missing'){body=boxed(rows,o,{x:25,y:110,w:540,h:315});body+=T(750,150,scene.view==='invalid'?'C/E重叠，检查未通过':'缺少E，检查未通过',25,'#a54c35')+T(750,230,'诊断盒面积 '+report.bbox.area,25)+T(750,310,'有效密度：—',28)+T(750,385,'有效空余：—',28);}
 else if(scene.view==='pipeline'){['读取Lab2的完整检查报告','非法：保留错误和诊断几何，分数留空','合法：用max−min算真实包围盒','分别使用外框/包围盒作分母','在相同规则和目标下比较'].forEach((s,i)=>{const y=105+i*71;body+=R(60,y,840,55,p*5>=i?'#e4efde':'#f3f6ef')+T(82,y+37,`${i+1}. ${s}`,24,'#365e49','start');});}
 else if(scene.view==='tradeoff'){body=mini(BASE03,45,155,390,205,'原来：9×3=27')+mini(TRADEOFF03,525,155,390,205,'只动E：7×4=28')+T(480,110,'宽9→7，高3→4',28);if(p>.3)body+=T(480,455,'面积没有改善；盒密度85.19%→82.14%',27,'#a15334');}
 else if(scene.view==='fit-filter'){const enter=Math.max(0,Math.min(1,p/.35)),ease=enter*enter*(3-2*enter);body+=`<g transform="translate(${(-260*(1-ease)).toFixed(1)} 0)" opacity="${ease.toFixed(2)}">`+board(CANDIDATES03[0].rows,[4,4],{x:25,y:160,w:380,h:220,interactive:false})+'</g>';body+=`<g transform="translate(${(260*(1-ease)).toFixed(1)} 0)" opacity="${ease.toFixed(2)}">`+board(CANDIDATES03[1].rows,[4,4],{x:540,y:160,w:380,h:220,interactive:false})+'</g>';body+=T(225,110,'X：6×2=12',28)+T(735,110,'Y：3×4=12',28);if(p>.5)body+=T(225,445,'宽 6 > 4 → 装不进',23,'#a15334')+`<path d="M180 405L270 405" stroke="#a34231" stroke-width="3"/>`;if(p>.7)body+=T(735,445,'宽 3、高 4 → 正好放下',23,'#386f4c')+T(735,478,'✓',26,'#2d7865');}
 else if(scene.view==='budget'||scene.view==='budget-values'){body=R(40,130,415,300)+R(505,130,415,300)+T(247,177,'空余 / 模块面积 = γ',25)+T(712,177,'空余 / 总区域面积 = f',25);if(scene.view==='budget'){if(p>.15)body+=T(247,250,'D = γ S',28)+T(712,250,'S = T (1−f)',28);if(p>.4)body+=T(247,335,'T = S (1+γ)',30)+T(712,335,'T = S / (1−f)',30);body+=T(480,466,'S为模块面积，D为空余，T为总区域面积；0≤f<1',20);}else{body+=T(247,260,'23 × 1.15',31)+T(712,260,'23 / 0.85',31);if(p>.2)body+=T(247,345,'26.45',38)+T(712,345,'≈27.06',38);body+=T(480,466,'预算等式不是一份可行布局的证明',23,'#9a5833');}}
 else if(scene.view==='report'){const r=metricsReport(BEST03);const lines=[`legal: true，errors: []`,`module_area: ${r.module_area}，outline_area: ${r.outline_area}`,`bbox: width=6，height=4，area=24`,`outline_density=23/80，packing_density=23/24`,`outline_dead=57，bbox_dead=1`];lines.forEach((s,i)=>{const th=.05+i*.14,show=Math.max(0,Math.min(1,(p-th)/.1));if(show>0)body+=R(55,110+i*69,850,53,'#eef4e8',i===4?'#c9a06d':'#b7c9b5')+T(80,145+i*69,s,24,'#355d49','start');});}
 else if(scene.view==='limits'){body=mini(BEST03,65,145,380,250,'只证明本模型下的几何结果')+T(720,160,'还没建模的数据',27)+T(720,235,'网表与引脚',26)+T(720,300,'时序与布线约束',26)+T(720,380,'不能凭面积给全面排名',24,'#9d5636');}
 else if(scene.view==='transfer'){['用平移，检验公式','换外框，先筛可行性','改变宽高，核对真实目标'].forEach((s,i)=>{const x=42+i*307;body+=R(x,160,278,220)+T(x+139,230,i+1,42,'#9b6337')+T(x+139,320,s,20);});}
 return`<defs><pattern id="collision" width="8" height="8" patternUnits="userSpaceOnUse" patternTransform="rotate(45)"><rect width="8" height="8" fill="#efc2ad"/><path d="M0 0V8" stroke="#a74330" stroke-width="3"/></pattern></defs>${T(35,44,trial?'自己的尝试':scene.title,28,'#1d3c31','start')}${T(925,44,'第 '+scene.chapter+' / 8 章',13,'#6b8373','end')}${body}${T(480,512,trial?'先看合法性，再比较你选择的指标':moving?'位置变化示意，落定后再检查和比较':scene.note,18)}`;
}
export function reportTrial(rows,scene){const r=metricsReport(rows,scene.outline||[10,8],scene.catalog);return r.legal?`当前合法。包围盒${f(r.bbox.width)}×${f(r.bbox.height)}=${f(r.bbox.area)}；外框密度${pct(r.outline_density)}，包围盒密度${pct(r.packing_density)}。`:'当前不能计有效分数：'+r.errors.map(describeError02).join('，');}
